// Exact lane-wise native AKAZE Gaussian/Scharr arithmetic from the qualified
// OpenCV 4.11 adaptation. See vendor/akaze-paged/LICENSE. No reduction across lanes.
#include <opencv2/core.hpp>
#include <opencv2/imgproc.hpp>
#include <wasm_simd128.h>
#include <cmath>
static int replicate(int p,int n){return p<0?0:p>=n?n-1:p;}
static int reflect101(int p,int n){if(n==1)return 0;while(p<0||p>=n)p=p<0?-p:2*n-p-2;return p;}
static v128_t madd(v128_t a,float b,v128_t c){return wasm_f32x4_relaxed_madd(a,wasm_f32x4_splat(b),c);}
void cloningAKAZEGaussian(cv::InputArray source,cv::OutputArray dest,cv::Size size,double sx,double sy,int border){
 CV_Assert(size.width==size.height&&(size.width==5||size.width==9)&&sx==sy&&border==cv::BORDER_REPLICATE&&source.type()==CV_32F);const cv::Mat input=source.getMat();const int w=input.cols,h=input.rows,n=size.width,r=n/2;const cv::Mat kernel=cv::getGaussianKernel(n,float(sx),CV_32F);const float*k=kernel.ptr<float>();cv::Mat row(h,w,CV_32F),result(h,w,CV_32F);
 for(int y=0;y<h;y++){const float*in=input.ptr<float>(y);float*out=row.ptr<float>(y);int x=0;for(;x<w;){if(x>=r&&x+3+r<w){v128_t a;if(n==5){auto near=wasm_f32x4_add(wasm_v128_load(in+x-1),wasm_v128_load(in+x+1)),far=wasm_f32x4_add(wasm_v128_load(in+x-2),wasm_v128_load(in+x+2));a=madd(wasm_v128_load(in+x),k[2],wasm_f32x4_mul(near,wasm_f32x4_splat(k[3])));a=madd(far,k[4],a);}else{a=wasm_f32x4_mul(wasm_v128_load(in+x-r),wasm_f32x4_splat(k[0]));for(int j=1;j<n;j++)a=madd(wasm_v128_load(in+x+j-r),k[j],a);}wasm_v128_store(out+x,a);x+=4;}else{auto at=[&](int xx){return in[replicate(xx,w)];};float a;if(n==5){float near=at(x-1)+at(x+1),far=at(x-2)+at(x+2);a=x<w/2*2?std::fma(at(x),k[2],near*k[3]):std::fma(near,k[3],at(x)*k[2]);a=std::fma(far,k[4],a);}else{a=at(x-r)*k[0];for(int j=1;j<n;j++)a=std::fma(at(x+j-r),k[j],a);}out[x++]=a;}}}
 for(int y=0;y<h;y++){const float*center=row.ptr<float>(y);float*out=result.ptr<float>(y);int x=0;for(;x+3<w;x+=4){auto a=wasm_f32x4_mul(wasm_v128_load(center+x),wasm_f32x4_splat(k[r]));for(int j=1;j<=r;j++)a=madd(wasm_f32x4_add(wasm_v128_load(row.ptr<float>(replicate(y-j,h))+x),wasm_v128_load(row.ptr<float>(replicate(y+j,h))+x)),k[r+j],a);wasm_v128_store(out+x,a);}for(;x<w;x++){float a=center[x]*k[r];for(int j=1;j<=r;j++)a=std::fma(row.ptr<float>(replicate(y-j,h))[x]+row.ptr<float>(replicate(y+j,h))[x],k[r+j],a);out[x]=a;}}
 result.copyTo(dest);
}
void cloningAKAZEScharr(cv::InputArray source,cv::OutputArray dest,int depth,int dx,int dy,double scale,double delta,int border){
 CV_Assert(source.type()==CV_32F&&depth==CV_32F&&dx+dy==1&&scale==1&&delta==0&&border==cv::BORDER_DEFAULT);const cv::Mat input=source.getMat();const int w=input.cols,h=input.rows;cv::Mat row(h,w,CV_32F),result(h,w,CV_32F);
 for(int y=0;y<h;y++){const float*in=input.ptr<float>(y);float*out=row.ptr<float>(y);for(int x=0;x<w;){if(x>=1&&x+4<w){auto a=wasm_v128_load(in+x-1),b=wasm_v128_load(in+x+1),center=wasm_v128_load(in+x);wasm_v128_store(out+x,dx?wasm_f32x4_sub(b,a):madd(center,10.f,wasm_f32x4_mul(wasm_f32x4_add(a,b),wasm_f32x4_splat(3.f))));x+=4;}else{float a=in[reflect101(x-1,w)],b=in[reflect101(x+1,w)],c=in[x];out[x]=dx?b-a:x<w/2*2?std::fma(c,10.f,(a+b)*3.f):std::fma(a+b,3.f,c*10.f);x++;}}}
 for(int y=0;y<h;y++){const float*a=row.ptr<float>(reflect101(y-1,h)),*b=row.ptr<float>(reflect101(y+1,h)),*c=row.ptr<float>(y);float*out=result.ptr<float>(y);int x=0;for(;x+3<w;x+=4)wasm_v128_store(out+x,dx?madd(wasm_f32x4_add(wasm_v128_load(a+x),wasm_v128_load(b+x)),3.f,wasm_f32x4_mul(wasm_v128_load(c+x),wasm_f32x4_splat(10.f))):wasm_f32x4_sub(wasm_v128_load(b+x),wasm_v128_load(a+x)));for(;x<w;x++)out[x]=dx?std::fma(a[x]+b[x],3.f,c[x]*10.f):b[x]-a[x];}
 result.copyTo(dest);
}
void cloningAKAZESep(cv::InputArray source,cv::OutputArray dest,int depth,cv::InputArray kernelX,cv::InputArray kernelY){
 const cv::Mat input=source.getMat(),kx=kernelX.getMat(),ky=kernelY.getMat();CV_Assert(input.type()==CV_32F&&depth==CV_32F&&kx.type()==CV_32F&&ky.type()==CV_32F);const int w=input.cols,h=input.rows,nx=kx.total(),ny=ky.total(),rx=nx/2,ry=ny/2;const float*xk=kx.ptr<float>(),*yk=ky.ptr<float>();const bool sx=xk[0]==xk[nx-1],sy=yk[0]==yk[ny-1];cv::Mat row(h,w,CV_32F),result(h,w,CV_32F);
 for(int y=0;y<h;y++){const float*in=input.ptr<float>(y);float*out=row.ptr<float>(y);for(int x=0;x<w;){if(x>=rx&&x+3+rx<w){v128_t a;if(nx<=5){auto lo=wasm_v128_load(in+x-1),hi=wasm_v128_load(in+x+1),near=sx?wasm_f32x4_add(lo,hi):wasm_f32x4_sub(hi,lo);a=sx?madd(wasm_v128_load(in+x),xk[rx],wasm_f32x4_mul(near,wasm_f32x4_splat(xk[rx+1]))):wasm_f32x4_mul(near,wasm_f32x4_splat(xk[rx+1]));if(nx==5){lo=wasm_v128_load(in+x-2);hi=wasm_v128_load(in+x+2);a=madd(sx?wasm_f32x4_add(lo,hi):wasm_f32x4_sub(hi,lo),xk[4],a);}}else{a=wasm_f32x4_mul(wasm_v128_load(in+x-rx),wasm_f32x4_splat(xk[0]));for(int j=1;j<nx;j++)a=madd(wasm_v128_load(in+x+j-rx),xk[j],a);}wasm_v128_store(out+x,a);x+=4;}else{auto at=[&](int xx){return in[reflect101(xx,w)];};float a;if(nx<=5){float near=sx?at(x-1)+at(x+1):at(x+1)-at(x-1);a=sx?(x<w/2*2?std::fma(at(x),xk[rx],near*xk[rx+1]):std::fma(near,xk[rx+1],at(x)*xk[rx])):near*xk[rx+1];if(nx==5){float far=sx?at(x-2)+at(x+2):at(x+2)-at(x-2);a=std::fma(far,xk[4],a);}}else{a=at(x-rx)*xk[0];for(int j=1;j<nx;j++)a=std::fma(at(x+j-rx),xk[j],a);}out[x++]=a;}}}
 for(int y=0;y<h;y++){const float*center=row.ptr<float>(y);float*out=result.ptr<float>(y);int x=0;for(;x+3<w;x+=4){auto a=sy?wasm_f32x4_mul(wasm_v128_load(center+x),wasm_f32x4_splat(yk[ry])):wasm_f32x4_splat(0);for(int j=1;j<=ry;j++){auto lo=wasm_v128_load(row.ptr<float>(reflect101(y-j,h))+x),hi=wasm_v128_load(row.ptr<float>(reflect101(y+j,h))+x);a=madd(sy?wasm_f32x4_add(hi,lo):wasm_f32x4_sub(hi,lo),yk[ry+j],a);}wasm_v128_store(out+x,a);}for(;x<w;x++){float a=sy?center[x]*yk[ry]:0;for(int j=1;j<=ry;j++){float lo=row.ptr<float>(reflect101(y-j,h))[x],hi=row.ptr<float>(reflect101(y+j,h))[x];a=std::fma(sy?hi+lo:hi-lo,yk[ry+j],a);}out[x]=a;}}
 result.copyTo(dest);
}
